use crate::{CoreError,Result};
use encoding_rs::{GBK,SHIFT_JIS,UTF_16BE,UTF_16LE,UTF_8,WINDOWS_1252};
use serde::{Deserialize,Serialize};
#[derive(Debug,Clone,Copy,PartialEq,Eq,Serialize,Deserialize)]#[serde(rename_all="snake_case")]pub enum TextEncoding{Utf8,Utf16Le,Utf16Be,Windows1252,Iso8859_1,ShiftJis,Gbk}
impl Default for TextEncoding{fn default()->Self{Self::Utf8}}
impl TextEncoding{pub fn label(self)->&'static str{match self{Self::Utf8=>"UTF-8",Self::Utf16Le=>"UTF-16 LE",Self::Utf16Be=>"UTF-16 BE",Self::Windows1252=>"Windows-1252",Self::Iso8859_1=>"ISO-8859-1",Self::ShiftJis=>"Shift-JIS",Self::Gbk=>"GBK"}}pub fn detect(bytes:&[u8])->(Self,bool,usize){if bytes.starts_with(&[0xEF,0xBB,0xBF]){return(Self::Utf8,true,3)}if bytes.starts_with(&[0xFF,0xFE]){return(Self::Utf16Le,true,2)}if bytes.starts_with(&[0xFE,0xFF]){return(Self::Utf16Be,true,2)}if std::str::from_utf8(bytes).is_ok(){return(Self::Utf8,false,0)}let(s,_,e)=SHIFT_JIS.decode(bytes);if !e&&s.chars().any(|c|!c.is_ascii()){return(Self::ShiftJis,false,0)}let(s,_,e)=GBK.decode(bytes);if !e&&s.chars().any(|c|!c.is_ascii()){return(Self::Gbk,false,0)}(Self::Windows1252,false,0)}pub fn decode(self,bytes:&[u8])->Result<String>{let bom=match self{Self::Utf8 if bytes.starts_with(&[0xEF,0xBB,0xBF])=>3,Self::Utf8 if bytes.starts_with(&[0xFF,0xFE])||bytes.starts_with(&[0xFE,0xFF])=>2,Self::Utf16Le if bytes.starts_with(&[0xFF,0xFE])=>2,Self::Utf16Be if bytes.starts_with(&[0xFE,0xFF])=>2,_=>0};let effective=if matches!(self,Self::Utf8)&&bytes.starts_with(&[0xFF,0xFE]){Self::Utf16Le}else if matches!(self,Self::Utf8)&&bytes.starts_with(&[0xFE,0xFF]){Self::Utf16Be}else{self};let bytes=&bytes[bom.min(bytes.len())..];if effective==Self::Iso8859_1{return Ok(bytes.iter().map(|b|char::from(*b)).collect())}let mut decoder=effective.encoding().new_decoder();let(text,_,errors)=decoder.decode(bytes);if errors{return Err(CoreError::Encoding(format!("invalid {} data",self.label())))}Ok(text.into_owned())}pub fn encode(self,text:&str,bom:bool)->Vec<u8>{let mut out=Vec::new();if bom{match self{Self::Utf8=>out.extend_from_slice(&[0xEF,0xBB,0xBF]),Self::Utf16Le=>out.extend_from_slice(&[0xFF,0xFE]),Self::Utf16Be=>out.extend_from_slice(&[0xFE,0xFF]),_=>{}}}if self==Self::Iso8859_1{out.extend(text.chars().map(|c|if c as u32<=255{c as u8}else{b'?'}));return out}let(s,_,_)=self.encoding().encode(text);out.extend_from_slice(&s);out}fn encoding(self)->&'static encoding_rs::Encoding{match self{Self::Utf8=>UTF_8,Self::Utf16Le=>UTF_16LE,Self::Utf16Be=>UTF_16BE,Self::Windows1252|Self::Iso8859_1=>WINDOWS_1252,Self::ShiftJis=>SHIFT_JIS,Self::Gbk=>GBK}}}
